{"explanation":"The vertex of y = a(x − h)² + k is (h, k). Changing h moves the parabola left or right, while changing k moves it up or down. The value a controls its shape: larger |a| makes it narrower, and a negative value flips it downward. Move the sliders to see each effect.","manimCode":"const ax = new Axes({
  xRange: [-4, 4, 1],
  yRange: [-3.5, 4.5, 1],
  xLength: 8,
  yLength: 5.2,
  tips: false
});
ax.moveTo([-1.2, -0.15, 0]);

const title = new Text({ text: 'y = a(x − h)² + k', color: WHITE, fontSize: 36 });
title.moveTo([-1.2, 3.25, 0]);

let a = 0.7;
let h = 0;
let k = 0;

function makeCurve() {
  let left = -4;
  let right = 4;
  if (Math.abs(a) > 1e-8) {
    const radius = Math.sqrt((a > 0 ? 4.5 - k : k + 3.5) / Math.abs(a));
    left = Math.max(-4, h - radius);
    right = Math.min(4, h + radius);
  }
  return ax.plot(x => a * (x - h) * (x - h) + k, {
    color: YELLOW,
    xRange: [left, right],
    numSamples: 240
  });
}

let curve = makeCurve();
const vertex = new Dot({ point: ax.c2p(h, k), color: ORANGE });
const symmetry = new Polygon({
  vertices: [ax.c2p(h, -3.5), ax.c2p(h, 4.5)],
  color: TEAL
});
symmetry.setStrokeWidth(2);
symmetry.setFillOpacity(0);
symmetry.setOpacity(0.45);

function makeReadout() {
  const label = new Text({
    text: `a = ${a.toFixed(1)}    h = ${h.toFixed(1)}    k = ${k.toFixed(1)}    vertex = (${h.toFixed(1)}, ${k.toFixed(1)})`,
    color: WHITE,
    fontSize: 23
  });
  label.moveTo([-1.2, -3.35, 0]);
  return label;
}
let readout = makeReadout();

await scene.play(new Write(title));
await scene.play(new Create(ax));
scene.add(symmetry);
await scene.play(new Create(curve));
await scene.play(new FadeIn(vertex));
scene.add(readout);

function refresh() {
  scene.remove(curve);
  curve = makeCurve();
  scene.add(curve);
  vertex.moveTo(ax.c2p(h, k));
  symmetry.setVertices([ax.c2p(h, -3.5), ax.c2p(h, 4.5)]);
  scene.remove(readout);
  readout = makeReadout();
  scene.add(readout);
}

const controls = new Controls(scene, { position: 'top-right', theme: 'dark', width: 260 });
controls.addSlider({ label: 'a: stretch / flip', min: -1.5, max: 1.5, value: a, step: 0.1, onChange: v => { a = v; refresh(); } });
controls.addSlider({ label: 'h: left / right', min: -2, max: 2, value: h, step: 0.1, onChange: v => { h = v; refresh(); } });
controls.addSlider({ label: 'k: down / up', min: -2, max: 2, value: k, step: 0.1, onChange: v => { k = v; refresh(); } });

await scene.wait(999999);"}

